export const audiusVietnamTracks = _ROWS.map(([id, title, artist, handle, sec, genre, album, playCount, hi, path, mi]) => {
  const img = _H[hi] + path;
  return {
    id: 'aud-' + id,
    audiusId: id,
    title,
    artist,
    handle,
    duration: Math.floor(sec / 60) + ':' + String(sec % 60).padStart(2, '0'),
    durationSeconds: sec,
    genre,
    album: album === 0 ? genre : album,
    playCount,
    audioUrl: 'https://api.audius.co/v1/tracks/' + id + '/stream?app_name=SoundStream',
    img,
    artwork: { url: img, mirrors: mi.map((i) => _H[i]) }
  };
});
